/* Preview pages using the same catalogue records. */
const consumerPens = [
 {park:'CBE',pen:'Castro 1',mode:'Lump sum',count:60,kg:38,gain:172},
 {park:'CBE',pen:'Castro 2',mode:'Lump sum',count:73,kg:33.4,gain:175},
 {park:'CBE',pen:'Castro 3',mode:'Lump sum',count:60,kg:30.8,gain:165}
];
let consumerRateEditing=false;
let consumerRenderingModule=null;
function consumerAllowed(key,module=consumerRenderingModule){return typeof configValuesForModule!=='function'||configValuesForModule(module).some(i=>i.configKey===key);}
let consumerPenMinimum=null;
function consumerScopedPens(){const scope=typeof productionScope==='function'?productionScope():'All parks';return consumerPens.filter(p=>scope==='All parks'||p.park===scope);}
function consumerWeightSummary(pens=consumerPens,threshold=35){const count=pens.reduce((n,p)=>n+p.count,0),weight=pens.reduce((n,p)=>n+p.count*p.kg,0);return {count,weight,average:count?weight/count:0,above:pens.filter(p=>p.kg>=threshold).reduce((n,p)=>n+p.count,0),gain:count?pens.reduce((n,p)=>n+p.count*p.gain,0)/count:0};}
function consumerValuation(weight,rate){return weight*rate;}
function consumerValue(key,fallback){if(!consumerAllowed(key))return null;const i=typeof configValueByKey==='function'?configValueByKey(key):null;return i&&i.value!==null&&i.value!==undefined&&i.value!==''?i.value:fallback;}
function consumerNumber(key,fallback){if(!consumerAllowed(key))return null;return typeof configNumber==='function'?configNumber(key,fallback):fallback;}
function consumerConfigLink(key,label='View configuration'){if(!consumerAllowed(key))return '<span class="muted">Not linked to this module</span>';const i=typeof configValueByKey==='function'?configValueByKey(key):null;return i?`<button class="consumer-link" onclick="itemModal('${esc(i.id)}')">${esc(label)}</button>`:`<span class="muted">Configuration unavailable</span>`;}
function consumerSettingDisplay(key,suffix='',prefix=''){const value=consumerNumber(key,null);return value===null||value===undefined?'Configuration unavailable':prefix+String(value)+suffix;}
function consumerNotice(){return '<p class="consumer-preview-note">Local preview · changes stay in this browser.</p>';}
function consumerCard(label,value,sub){return `<section class="consumer-kpi"><div class="lab">${esc(label)}</div><div class="val">${esc(value)}</div><div class="sub">${esc(sub)}</div></section>`;}
function consumerTable(headers,rows){return `<div class="tablewrap"><table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`;}
function consumerHeading(title,sub=''){return `<div class="consumer-heading"><h1>${esc(title)}</h1>${sub?`<p>${esc(sub)}</p>`:''}</div>`;}
function consumerFormat(n,d=0){return Number(n).toLocaleString('en-IN',{maximumFractionDigits:d,minimumFractionDigits:d});}
function renderConsumerSurface(module,label){const el=document.querySelector('#content');if(!el)return false;consumerRenderingModule=module;
 const required={'ADG Analytics':['reporting_weight_30','reporting_weight_35'],'Farm value':['valuation_fattening_rate'],'Feed Config':['feed_ration_sample','removal_cutoff'],'Sales Config':['market_call_time'],'Vaccination plan':['vaccination_capacity']}[label];
 if(required&&required.some(key=>!consumerAllowed(key,module))){el.innerHTML=consumerHeading(label)+'<section class="card"><h2>Configuration needs attention</h2><p>A required configuration is archived or is no longer linked to this module. Restore its module relation in Items Config before using this preview.</p><button onclick="go(\'Items\',\'Registry\')">Items Config</button></section>'+consumerNotice();return true;}
 if(module==='Weighing'&&label==='ADG Analytics'){
 const t30=consumerNumber('reporting_weight_30',30),t35=consumerNumber('reporting_weight_35',35),pens=consumerScopedPens(),s=consumerWeightSummary(pens),a=consumerWeightSummary(pens,t30),b=consumerWeightSummary(pens,t35);
 el.innerHTML=`<div class="consumer-filterbar"><label>Park <select disabled><option>${esc(typeof productionScope==='function'?productionScope():'All parks')} · sample pens</option></select></label><label>Period <button disabled>▦ 03/08/2026 to 15/09/2026</button></label><label>Weighing <select disabled><option>Lump sum</option></select></label><label>Sex <select disabled><option>Male</option></select></label><label>Origin <select disabled><option>All</option></select></label><button class="consumer-download" onclick="consumerDownloadWeights()">↓ Download</button></div><div class="consumer-segments" aria-label="Analytics views">${['General','Breed-wise','Birth-wise','Pen-wise','Weight-wise','Time-wise','Comparison'].map((x,i)=>`<button ${i?'disabled':''} class="${i?'':'active'}">${x}</button>`).join('')}</div><p class="muted">Pens weighed: ${pens.length} / ${pens.length} · Sample of visible pen rows</p><div class="consumer-kpis">${consumerCard('Individual · Lump-sum',`0 · ${s.count}`,`${s.count} weighed in the sample`)}${consumerCard('Total weight',consumerFormat(s.weight)+' kg','of the kids actually weighed')}${consumerCard('Average weight',consumerFormat(s.average,1)+' kg','per kid, across sample pens')}${consumerCard('Over '+t30+' kg',a.above,`${s.count} weighed · a whole pen counts at its average`)}${consumerCard('Over '+t35+' kg',b.above,`${s.count} weighed · a whole pen counts at its average`)}</div><div class="consumer-kpis three">${consumerCard('All parks — daily gain',consumerFormat(s.gain)+' g','sample pens only')}${consumerCard('CBE — daily gain',consumerFormat(s.gain)+' g',`kids weighed · ${s.count}`)}</div><section class="card consumer-panel"><h2>Pens</h2><p>Total weight covers the kids actually weighed. Reporting thresholds classify this sample; they do not prohibit a sale.</p><div class="consumer-filterbar consumer-pen-filter"><label>Average weight (kg) <select id="consumer-weight-mode"><option value="all">All</option><option value="minimum" ${consumerPenMinimum!==null?'selected':''}>At least</option></select></label><input aria-label="Average weight minimum" id="consumer-weight-min" type="number" min="0" step="any" value="${consumerPenMinimum??''}"><button onclick="consumerApplyPenFilter()">Apply</button></div>${consumerTable(['Park','Pen','Weighing','Animals weighed','Average weight','Daily gain','Total weight','Last weighed'],pens.filter(p=>consumerPenMinimum===null||p.kg>=consumerPenMinimum).map(p=>`<tr><td>${p.park}</td><td><b>${p.pen}</b></td><td><span class="badge">${p.mode}</span></td><td>${p.count}</td><td>${p.kg} kg</td><td>${p.gain} g</td><td>${consumerFormat(p.kg*p.count)} kg</td><td>14/09/2026</td></tr>`))}</section><details class="consumer-settings"><summary>Reporting configuration</summary><p>These thresholds are hardcoded in the inspected application. These values can be configured centrally.</p><div class="actions">${consumerConfigLink('reporting_weight_30','Over '+t30+' kg')}${consumerConfigLink('reporting_weight_35','Over '+t35+' kg')}</div></details>${consumerNotice()}`;return true;
 }
 if(module==='Sales'&&label==='Farm value'){
 const r=consumerNumber('valuation_fattening_rate',450),s=consumerWeightSummary(consumerScopedPens()),value=consumerValuation(s.weight,r);
 el.innerHTML=consumerHeading('Farm value','Indicative valuation of the sample population')+`<div class="consumer-kpis three">${consumerCard('Fattening animals',s.count,'sample weighed animals')}${consumerCard('Total live weight',consumerFormat(s.weight)+' kg','sample pen weights')}${consumerCard('Indicative value','₹'+consumerFormat(value),'weight × configured valuation rate')}</div><section class="card consumer-panel"><h2>Valuation breakdown</h2>${consumerTable(['Category','Animals','Weight basis','Rate / kg','Indicative value'],[`<tr><td>Fattening animals</td><td>${s.count}</td><td>${consumerFormat(s.weight)} kg</td><td>₹${consumerFormat(r)}</td><td>₹${consumerFormat(value)}</td></tr>`])}<div class="consumer-row-actions">${consumerConfigLink('valuation_fattening_rate','View valuation rate')}</div></section><p class="muted">The existing source uses ₹450/kg for fattening valuation. Central editing is proposed here. Recorded sales and market observations stay separate.</p><details class="consumer-settings"><summary>Other Sales-owned valuation assumptions</summary>${consumerTable(['Category','Assumed weight','Rate / kg'],[['Adult females','adult_female'],['Adult males / bucks','adult_male'],['K0','k0'],['K1','k1'],['K2','k2'],['K3','k3']].map(([label,key])=>[label,consumerSettingDisplay('valuation_'+key+'_weight',' kg'),consumerSettingDisplay('valuation_'+key+'_rate','','₹')]).map(a=>`<tr>${a.map(x=>`<td>${x}</td>`).join('')}</tr>`))}</details>${consumerNotice()}`;return true;
 }
 if(module==='Sales'&&label==='Sales Config'){
 el.innerHTML=consumerHeading('Sales Config','Sales register and market survey configuration')+`<section class="card consumer-panel"><div class="cardheader"><h2>Sales</h2><div class="actions"><button disabled title="Operational entry is outside this configuration preview">Record sale</button><button disabled>Tag animals to sale</button></div></div>${consumerTable(['Sale','Buyer','Date','Animals','Weight','Value','Status'],['<tr><td colspan="7" class="muted">No transaction rows copied into this configuration preview.</td></tr>'])}</section><section class="card consumer-panel"><h2>Market survey</h2><div class="linkline"><span>Call time <b>${esc(consumerValue('market_call_time','08:00'))}</b></span>${consumerConfigLink('market_call_time','Edit call time')}</div><p class="muted">Cities, survey questions and recorded market prices keep their existing purpose. A valuation-rate change does not change a sale or market observation.</p></section><section class="card consumer-panel"><h2>Shared configuration</h2><p>Purchase and selling-rate definitions can be authored in the central configuration. Actual transactions remain in this register.</p><div class="actions"><button onclick="go('Items','Registry')">Items Config</button><button onclick="productionNavigate('Sales','Farm value')">Farm value</button></div></section>${consumerNotice()}`;return true;
 }
 if(module==='Feed'&&label==='Feed Config'){
 const rate=consumerNumber('feed_ration_sample',1900),i=typeof configValueByKey==='function'?configValueByKey('feed_ration_sample'):null;
 el.innerHTML='<div class="consumer-breadcrumb">FEED / <b>RATION GRID</b></div>'+consumerHeading('Feed Config — Ration Rules')+`<p class="consumer-scope-note">Local sample: this ration is park-specific. The existing product authors ration grids and feeding schedules per park. The controls below show the existing filter layout; unsupported sample filters are disabled.</p><section class="card consumer-panel"><div class="cardheader"><h2>Ration grid</h2><span class="muted">Ration group × pen tag × feed item → grams per head per day</span></div><div class="consumer-filterbar consumer-feed-filter"><label>Park <select disabled><option>Sample park</option></select></label><label>Breed <select disabled><option>All</option></select></label><label>Pen tag <select disabled><option>All</option></select></label><label>Feed item <select disabled><option>All</option></select></label><label>Grams / head / day <select disabled><option>All</option></select></label><input aria-label="Ration quantity filter unavailable in sample" disabled type="number"><button disabled>Apply</button></div>${consumerTable(['Ration group','Pen tag','Feed item','Grams / head / day','Effective from','Effective to','Edit rate'],[`<tr><td>Boer</td><td>Buck</td><td>Dry Masoor Bhusa</td><td>${consumerRateEditing?'<input id="consumer-feed-rate" aria-label="Grams per head per day" type="number" min="0" step="any" value="'+rate+'">':consumerFormat(rate,3)}</td><td><span class="badge">In force</span><br>05/08/2026</td><td>—</td><td>${consumerRateEditing?'<button onclick="consumerApplyFeedRate()">Apply</button> <button onclick="consumerRateEditing=false;renderConsumerSurface(\'Feed\',\'Feed Config\')">Cancel</button>':`<button ${!canEdit()||!i?'disabled':''} onclick="consumerRateEditing=true;renderConsumerSurface('Feed','Feed Config')">Edit rate</button>`}</td></tr>`])}<p id="consumer-rate-error" class="error" role="status"></p><div class="consumer-row-actions">${consumerConfigLink('feed_ration_sample','View shared configuration')}</div></section><section class="card consumer-panel"><h2>Feeding schedule</h2>${consumerTable(['Workflow','Direction','Correction','Transport'],['<tr><td>Normal</td><td>07:00</td><td>14:00</td><td>15:30</td></tr>','<tr><td>Experiment</td><td>14:00</td><td>14:00</td><td>15:30</td></tr>'])}</section><section class="card consumer-panel"><h2>Feed / water removal</h2><div class="linkline"><span>Cutoff <b>${esc(consumerValue('removal_cutoff','21:00'))}</b></span>${consumerConfigLink('removal_cutoff','Edit cutoff')}</div></section>${consumerNotice()}`;return true;
 }
 if(module==='Health'&&label==='Health Config'){
 el.innerHTML=consumerHeading('Health Config','Treatment protocols')+`<section class="card consumer-panel"><div class="cardheader"><h2>Protocols</h2><button disabled>Add disease</button></div>${consumerTable(['Disease','Age band','Duration','Version',''],[['Fever','Adult','3 days'],['Fever','Kid','3 days'],['Acidosis','Adult','2 days'],['Abscesses','Adult','7 days']].map(a=>`<tr>${a.map(x=>`<td>${x}</td>`).join('')}<td><span class="badge">Live v1</span></td><td><button onclick="consumerProtocolInfo()">View</button></td></tr>`))}</section><section class="card consumer-panel"><h2>Available configured items</h2><p>Reusable item library items can be selected in the SOP editor. Medicines and the protocol's dose, route and schedule remain different records.</p>${consumerModuleItems('Health')}<button onclick="go('Health','Editor')">Review SOP editor</button></section>${consumerNotice()}`;return true;
 }
 if(module==='Preventive Care'&&label==='Vaccination plan'){
 el.innerHTML=consumerHeading('Vaccination plan','Published vaccine schedule')+`<section class="card consumer-panel"><div class="cardheader"><h2>Published plan v9</h2><span class="badge">Production-style reference</span></div><p>Vaccines, first doses, repeat timing, purpose rules and spacing rules stay in the Vaccination Plan. This prototype should not create a second vaccine catalogue or stock screen.</p>${consumerTable(['Vaccine','First doses','Repeats','Status'],['<tr><td>ET+TT</td><td>2 from date of birth · 1 on a drive · 1 follow-up</td><td>Every 26 weeks</td><td><span class="badge">in the plan</span></td></tr>','<tr><td>PPR</td><td>1 from date of birth · 1 on a drive</td><td>Every 3 years</td><td><span class="badge">in the plan</span></td></tr>','<tr><td>FMD</td><td>1 from date of birth · 1 on a drive</td><td>Every 274 days</td><td><span class="badge">in the plan</span></td></tr>','<tr><td>HS</td><td>1 from date of birth · 1 on a drive</td><td>Every 1 year</td><td><span class="badge">in the plan</span></td></tr>'])}</section><section class="card consumer-panel"><h2>Existing authoring surface</h2><p>Use Vaccination plan for vaccine rules. Use the module's own production screens for any stock or drive execution records.</p><div class="actions">${consumerConfigLink('vaccination_capacity','Plan capacity')}<button onclick="productionNavigate('Preventive Care','Vaccination plan')">Review vaccination plan</button></div></section>`;return true;
 }
 return false;
}
function consumerModuleItems(module){const list=typeof availableItems==='function'?availableItems(module):[];return `<div class="consumer-item-tags">${list.filter(i=>i.itemKind!=='config_value').map(i=>`<button onclick="itemModal('${esc(i.id)}')">${esc(i.name)}</button>`).join('')||'<span class="muted">No applicable catalogue items. Add or link one in Items Config.</span>'}</div>`;}
function consumerProtocolInfo(){modal('Treatment protocol', '<p>Existing Health configuration publishes a version per disease and age band. Medication, route, dose denominator, day and session belong to that protocol.</p><p>Clinical protocols stay in Health Config; reusable items are shown through SOP authoring.</p><button onclick="closeModal();go(\'Health\',\'Editor\')">Review SOP editor</button>');}
function consumerApplyFeedRate(){if(!canEdit())return;const input=document.querySelector('#consumer-feed-rate'),raw=input.value.trim(),n=Number(raw);if(!raw||!Number.isFinite(n)||n<0){document.querySelector('#consumer-rate-error').textContent='Enter a non-negative quantity. Zero is a configured value.';return;}const item=configValueByKey('feed_ration_sample');if(!item)return;item.value=n;item.revision=(item.revision||0)+1;record('Updated local feed ration configuration');consumerRateEditing=false;renderConsumerSurface('Feed','Feed Config');}
// Remove the earlier unsupported combined Sales policy from all reachable legacy views.
const consumerLegacyConfig=configView;
configView=function(){
 const names={Sales:'Sales Config',Weighing:'ADG Analytics',Feed:'Feed Config',Health:'Health Config','Preventive Care':'Vaccination plan'};
 if(names[current]&&renderConsumerSurface(current,names[current]))return;
 document.querySelector('#content').innerHTML='<section class="card"><h2>'+esc(current)+' configuration</h2><p>Use the reusable item library for reusable items and the existing SOP editor for this module’s typed procedure.</p><div class="actions"><button onclick="go(\'Items\',\'Registry\')">Items Config</button><button onclick="go(current,\'SOPs\')">SOPs</button></div></section>';
};
const consumerCommonView=commonView;
commonView=function(){consumerCommonView();if(tab==='Sharing'){const content=document.querySelector('#content');content.querySelectorAll('.two').forEach(x=>{if(x.textContent.includes('Sales → Weighing'))x.remove();});}};
if(typeof commitItem==='function'){
 const consumerCommitItem=commitItem;
 commitItem=function(item){consumerCommitItem(item);render();};
}

function consumerApplyPenFilter(){const mode=document.querySelector('#consumer-weight-mode').value,raw=document.querySelector('#consumer-weight-min').value;consumerPenMinimum=mode==='all'?null:(raw!==''&&Number.isFinite(Number(raw))&&Number(raw)>=0?Number(raw):null);renderConsumerSurface('Weighing','ADG Analytics');}
function consumerDownloadWeights(){const rows=[['Park','Pen','Animals weighed','Average weight kg'],...consumerScopedPens().map(p=>[p.park,p.pen,p.count,p.kg])];const url=URL.createObjectURL(new Blob([rows.map(r=>r.join(',')).join('\n')],{type:'text/csv'}));const a=document.createElement('a');a.href=url;a.download='sample-weights.csv';a.click();URL.revokeObjectURL(url);}
const consumerBoundPages={reporting_weight_30:['ADG Analytics'],reporting_weight_35:['ADG Analytics'],valuation_fattening_rate:['Farm value'],feed_ration_sample:['Feed Config'],removal_cutoff:['Feed Config'],market_call_time:['Sales Config'],vaccination_capacity:['Vaccination plan']};
if(typeof itemModal==='function'){
 const consumerItemModal=itemModal;
 itemModal=function(id){consumerItemModal(id);const item=id?itemById(id):null,pages=item?consumerBoundPages[item.configKey]:null,form=document.querySelector('#itemform');if(pages&&form)form.insertAdjacentHTML('afterbegin',`<div class="notice"><b>Used by ${pages.map(esc).join(', ')}</b><br>This preview reads the same saved record and revision. Archiving it or removing the consuming module link blocks that page until the relation is restored.</div>`);};
}
